      for (var d = 1; d <= 6 && !(leftTerrain && rightTerrain); d++) {
        if (!isSky(x - d, y)) leftTerrain = true;
        if (!isSky(x + d, y)) rightTerrain = true;
      }
      if (leftTerrain && rightTerrain) holes++;
